-- Recipes part 3/4: insert-only.
do $seed$
declare d jsonb := '[{"slug":"kaddu-ki-sabzi","name":"Khatta Meetha Kaddu","description":"Sweet-and-sour pumpkin with fenugreek seeds, jaggery and tamarind.","category":"Vegetables","cuisine":"Pakistani","minutes":30,"servings":4,"taste":{"sweet":6,"salty":4,"sour":5,"spicy":3},"lines":[["Pumpkin (Kaddu)",600,"600 g, cubed"],["Jaggery (Gur)",25,"2 tbsp"],["Tamarind (Imli)",15,"1 tbsp pulp"],["Fenugreek (Methi Dana)",2,"1/2 tsp"],["Fennel Seeds (Saunf)",3,"1 tsp"],["Red Chilli Powder",3,"3/4 tsp"],["Turmeric (Haldi)",2,"1/2 tsp"],["Mustard Oil",30,"2 tbsp"],["Salt",5,"1 tsp"]],"steps":["Heat mustard oil and crackle the fenugreek and fennel seeds.","Add pumpkin, turmeric, chilli and salt; cover and cook for 12 minutes, mashing lightly.","Stir in jaggery and tamarind and cook for 3 more minutes."]},{"slug":"band-gobhi","name":"Band Gobhi Matar","description":"Shredded cabbage and peas stir-fried with cumin and green chillies.","category":"Vegetables","cuisine":"Pakistani","minutes":25,"servings":4,"taste":{"sweet":2,"salty":5,"sour":2,"spicy":4},"lines":[["Cabbage",500,"1 small, shredded"],["Green Peas",150,"1 cup"],["Tomato",100,"1"],["Green Chilli",10,"2"],["Cumin (Zeera)",3,"1 tsp"],["Turmeric (Haldi)",2,"1/2 tsp"],["Red Chilli Powder",3,"3/4 tsp"],["Cooking Oil",30,"2 tbsp"],["Salt",6,"1 tsp"]],"steps":["Crackle cumin in oil, add the tomato and spices.","Add the cabbage, peas, green chillies and salt.","Cover and cook on low heat for 12 minutes, then stir-fry until dry."]},{"slug":"lauki-chana-dal","name":"Lauki Chana Dal","description":"Bottle gourd and split chickpeas cooked together, finished with a garlic tadka.","category":"Lentils","cuisine":"Pakistani","minutes":50,"servings":4,"taste":{"sweet":1,"salty":5,"sour":3,"spicy":4},"lines":[["Bottle Gourd (Lauki)",400,"1 medium, cubed"],["Chana Dal",150,"3/4 cup, soaked"],["Tomato",150,"1 large"],["Onion",100,"1"],["Turmeric (Haldi)",2,"1/2 tsp"],["Red Chilli Powder",4,"1 tsp"],["Garlic",10,"4 cloves"],["Cumin (Zeera)",3,"1 tsp"],["Cooking Oil",40,"3 tbsp"],["Salt",7,"1 1/4 tsp"]],"steps":["Boil the chana dal with turmeric until half cooked (20 minutes).","Fry the onion and tomato with chilli and salt; add the dal and lauki.","Cover and cook for 15 minutes until both are tender.","Make a tadka of cumin and sliced garlic in hot oil and pour over."]},{"slug":"arvi-masala","name":"Arvi Masala","description":"Colocasia cooked dry with carom seeds and dried mango powder.","category":"Vegetables","cuisine":"Pakistani","minutes":40,"servings":4,"taste":{"sweet":1,"salty":5,"sour":4,"spicy":5},"lines":[["Colocasia (Arvi)",500,"500 g, boiled and peeled"],["Onion",100,"1"],["Carom Seeds (Ajwain)",2,"1/2 tsp"],["Red Chilli Powder",4,"1 tsp"],["Coriander Powder",5,"1 tsp"],["Dried Mango Powder (Amchur)",3,"1 tsp"],["Turmeric (Haldi)",2,"1/2 tsp"],["Cooking Oil",40,"3 tbsp"],["Salt",6,"1 tsp"]],"steps":["Slice the boiled arvi.","Crackle ajwain in oil, fry the onion until soft and add the spices.","Add the arvi and stir-fry until crisp at the edges (10 minutes); finish with amchur."]},{"slug":"moong-daal","name":"Moong Daal","description":"Yellow moong lentils simmered soft and finished with a cumin and garlic tadka.","category":"Lentils","cuisine":"Pakistani","minutes":35,"servings":4,"taste":{"sweet":1,"salty":5,"sour":2,"spicy":4},"lines":[["Moong Dal",200,"1 cup, washed"],["Turmeric (Haldi)",2,"1/2 tsp"],["Tomato",100,"1"],["Green Chilli",10,"2"],["Garlic",10,"4 cloves"],["Cumin (Zeera)",3,"1 tsp"],["Whole Red Chilli (Sabut Lal Mirch)",2,"2"],["Desi Ghee",25,"2 tbsp"],["Salt",6,"1 tsp"],["Fresh Coriander",8,"chopped"]],"steps":["Boil the dal with turmeric, tomato, green chilli and salt in 4 cups water until soft (25 minutes).","Heat ghee, fry cumin, garlic and whole red chillies until golden.","Pour the tadka over the dal and garnish with coriander."]},{"slug":"chana-daal","name":"Chana Daal Tadka","description":"Split chickpeas cooked until creamy, with an onion and tomato tadka.","category":"Lentils","cuisine":"Pakistani","minutes":50,"servings":4,"taste":{"sweet":1,"salty":5,"sour":3,"spicy":5},"lines":[["Chana Dal",200,"1 cup, soaked 1 hour"],["Onion",120,"1"],["Tomato",150,"1 large"],["Ginger Garlic Paste",10,"2 tsp"],["Turmeric (Haldi)",2,"1/2 tsp"],["Red Chilli Powder",4,"1 tsp"],["Cumin (Zeera)",3,"1 tsp"],["Garam Masala",2,"1/2 tsp"],["Cooking Oil",40,"3 tbsp"],["Salt",7,"1 1/4 tsp"]],"steps":["Boil the chana dal with turmeric and salt until soft (35 minutes).","Fry cumin and onion, add ginger garlic paste, tomato and chilli; cook until thick.","Mix the masala into the dal, simmer for 5 minutes and add garam masala."]},{"slug":"lobia-masala","name":"Lobia Masala","description":"Black-eyed beans in a thick, tangy onion-tomato masala.","category":"Lentils","cuisine":"Pakistani","minutes":60,"servings":4,"taste":{"sweet":1,"salty":6,"sour":4,"spicy":5},"lines":[["Black-eyed Beans (Lobia)",250,"1 1/4 cups, soaked overnight"],["Onion",150,"1 large"],["Tomato",200,"2"],["Ginger Garlic Paste",15,"1 tbsp"],["Red Chilli Powder",5,"1 tsp"],["Coriander Powder",5,"1 tsp"],["Turmeric (Haldi)",2,"1/2 tsp"],["Dried Mango Powder (Amchur)",2,"1/2 tsp"],["Cooking Oil",40,"3 tbsp"],["Salt",8,"1 1/2 tsp"]],"steps":["Pressure-cook or boil the lobia until tender.","Fry the onion, add ginger garlic paste, tomatoes and spices; cook until the oil separates.","Add the lobia with some cooking water and simmer for 10 minutes; finish with amchur."]},{"slug":"kala-chana","name":"Kala Chana Masala","description":"Black chickpeas cooked in a dark, spiced gravy.","category":"Lentils","cuisine":"Pakistani","minutes":70,"servings":4,"taste":{"sweet":1,"salty":6,"sour":4,"spicy":6},"lines":[["Black Chickpeas (Kala Chana)",250,"1 1/4 cups, soaked overnight"],["Onion",150,"1 large"],["Tomato",200,"2"],["Ginger Garlic Paste",15,"1 tbsp"],["Chana Masala",15,"1 1/2 tbsp"],["Pomegranate Seeds Dried (Anardana)",5,"1 tsp, ground"],["Cooking Oil",40,"3 tbsp"],["Salt",8,"1 1/2 tsp"],["Fresh Coriander",8,"chopped"]],"steps":["Boil the chickpeas until soft.","Fry the onion dark golden, add ginger garlic paste, tomatoes and chana masala.","Add the chickpeas with 1 cup cooking water and simmer for 15 minutes.","Stir in anardana and coriander."]},{"slug":"matar-pulao","name":"Matar Pulao","description":"Basmati rice cooked with green peas, cumin and whole spices.","category":"Rice","cuisine":"Pakistani","minutes":45,"servings":4,"taste":{"sweet":1,"salty":5,"sour":1,"spicy":2},"lines":[["Basmati Rice",400,"2 cups, soaked"],["Green Peas",200,"1 1/2 cups"],["Onion",120,"1, sliced"],["Cumin (Zeera)",3,"1 tsp"],["Bay Leaf (Tez Patta)",1,"2"],["Cloves (Laung)",1,"4"],["Black Cardamom (Bari Elaichi)",2,"1"],["Cooking Oil",50,"1/4 cup"],["Salt",10,"1 3/4 tsp"]],"steps":["Fry the onion golden with the whole spices and cumin.","Add the peas and stir for 2 minutes.","Add 3 1/2 cups water and salt and bring to a boil; add the rice.","Cook until the water is absorbed, then steam covered for 12 minutes."]},{"slug":"khichdi","name":"Moong Dal Khichdi","description":"Soft, comforting rice and moong lentils with ghee and cumin.","category":"Rice","cuisine":"Pakistani","minutes":35,"servings":4,"taste":{"sweet":1,"salty":5,"sour":1,"spicy":2},"lines":[["Basmati Rice",200,"1 cup"],["Moong Dal",100,"1/2 cup"],["Turmeric (Haldi)",2,"1/2 tsp"],["Cumin (Zeera)",3,"1 tsp"],["Desi Ghee",25,"2 tbsp"],["Onion",80,"1 small"],["Salt",7,"1 1/4 tsp"],["Yogurt (Dahi)",150,"to serve"]],"steps":["Wash rice and dal together.","Heat ghee, crackle cumin and fry the onion until soft.","Add rice, dal, turmeric, salt and 5 cups water; cook covered on low heat for 25 minutes until soft.","Serve with yogurt."]},{"slug":"prawn-biryani","name":"Prawn Biryani","description":"Spiced prawns layered with saffron rice and fried onions.","category":"Rice","cuisine":"Pakistani","minutes":60,"servings":5,"taste":{"sweet":1,"salty":6,"sour":5,"spicy":7},"lines":[["Prawns",500,"500 g, cleaned"],["Basmati Rice",400,"2 cups, soaked"],["Onion",200,"2, sliced"],["Tomato",200,"2"],["Yogurt (Dahi)",150,"2/3 cup"],["Biryani Masala",25,"2 1/2 tbsp"],["Ginger Garlic Paste",15,"1 tbsp"],["Green Chilli",15,"3"],["Fresh Mint (Pudina)",10,"a handful"],["Lemon",30,"1"],["Saffron (Zafran)",0.2,"a pinch"],["Cooking Oil",80,"1/3 cup"],["Salt",15,"2 1/2 tsp"]],"steps":["Fry the onions golden; keep half for layering.","Cook ginger garlic paste, tomatoes, yogurt and biryani masala until thick; add the prawns for 4 minutes only.","Boil the rice in salted water until 80% cooked and drain.","Layer rice and prawn masala with mint, chillies, lemon, fried onion and saffron milk.","Steam (dum) on low heat for 15 minutes."]},{"slug":"dahi-bhalla","name":"Dahi Bhalla","description":"Soft lentil dumplings soaked and served in sweet yogurt with chutneys and chaat masala.","category":"Snacks","cuisine":"Pakistani","minutes":60,"servings":6,"taste":{"sweet":6,"salty":5,"sour":5,"spicy":3},"lines":[["Mash Dal",200,"1 cup, soaked overnight"],["Yogurt (Dahi)",500,"2 cups, whisked"],["White Sugar",25,"2 tbsp"],["Tamarind Chutney",60,"1/4 cup"],["Mint Chutney",40,"3 tbsp"],["Chaat Masala",5,"1 1/2 tsp"],["Cumin (Zeera)",3,"1 tsp, roasted and ground"],["Red Chilli Powder",2,"1/2 tsp"],["Cooking Oil",40,"for frying (about 3 tbsp absorbed)"],["Salt",5,"1 tsp"]],"steps":["Grind the soaked dal to a fluffy batter with a little water and salt; beat for 5 minutes.","Drop spoonfuls into hot oil and fry golden; soak the bhallas in warm water for 15 minutes and squeeze gently.","Whisk the yogurt with sugar and a pinch of salt.","Arrange the bhallas, pour over the yogurt and top with chutneys, chaat masala, cumin and chilli."]}]'::jsonb; r jsonb; rid bigint; i int; missing text;
begin
select string_agg(distinct l->>0, ', ') into missing from jsonb_array_elements(d) r2, jsonb_array_elements(r2->'lines') l where not exists (select 1 from public.ingredients x where x.name = l->>0);
if missing is not null then raise exception 'Unknown ingredients: %', missing; end if;
for r in select * from jsonb_array_elements(d) loop
insert into public.curated_recipes(slug, name, description, category, cuisine, minutes, servings, taste, status, source) values (r->>'slug', r->>'name', r->>'description', r->>'category', r->>'cuisine', (r->>'minutes')::int, (r->>'servings')::int, r->'taste', 'published', 'curated') on conflict (slug) do nothing returning id into rid;
continue when rid is null;
for i in 0 .. jsonb_array_length(r->'lines') - 1 loop
insert into public.recipe_ingredients(recipe_id, ingredient_id, position, grams, display) select rid, x.id, i + 1, (r->'lines'->i->>1)::numeric, r->'lines'->i->>2 from public.ingredients x where x.name = r->'lines'->i->>0;
end loop;
for i in 0 .. jsonb_array_length(r->'steps') - 1 loop
insert into public.recipe_steps(recipe_id, position, body) values (rid, i + 1, r->'steps'->>i);
end loop;
end loop;
end $seed$;
select count(*) as published_recipes from public.curated_recipes where status = 'published';